    "\u5806/\u8d2a\u5fc3",
    "\u6709\u4e00\u4e2a\u00a0m x n\u00a0\u5927\u5c0f\u7684\u77e9\u5f62\u86cb\u7cd5\uff0c\u9700\u8981\u5207\u6210\u00a01 x 1\u00a0\u7684\u5c0f\u5757\u3002\n\n\u7ed9\u4f60\u6574\u6570\u00a0m\u00a0\uff0cn\u00a0\u548c\u4e24\u4e2a\u6570\u7ec4\uff1a\n\n\thorizontalCut \u7684\u5927\u5c0f\u4e3a\u00a0m - 1\u00a0\uff0c\u5176\u4e2d\u00a0horizontalCut[i]\u00a0\u8868\u793a\u6cbf\u7740\u6c34\u5e73\u7ebf i\u00a0\u5207\u86cb\u7cd5\u7684\u5f00\u9500\u3002\n\n\tverticalCut \u7684\u5927\u5c0f\u4e3a\u00a0n - 1\u00a0\uff0c\u5176\u4e2d\u00a0verticalCut[j]\u00a0\u8868\u793a\u6cbf\u7740\u5782\u76f4\u7ebf\u00a0j\u00a0\u5207\u86cb\u7cd5\u7684\u5f00\u9500\u3002\n\n\u4e00\u6b21\u64cd\u4f5c\u4e2d\uff0c\u4f60\u53ef\u4ee5\u9009\u62e9\u4efb\u610f\u4e0d\u662f\u00a01 x 1\u00a0\u5927\u5c0f\u7684\u77e9\u5f62\u86cb\u7cd5\u5e76\u6267\u884c\u4ee5\u4e0b\u64cd\u4f5c\u4e4b\u4e00\uff1a\n\n\t\u6cbf\u7740\u6c34\u5e73\u7ebf\u00a0i\u00a0\u5207\u5f00\u86cb\u7cd5\uff0c\u5f00\u9500\u4e3a\u00a0horizontalCut[i]\u00a0\u3002\n\n\t\u6cbf\u7740\u5782\u76f4\u7ebf\u00a0j\u00a0\u5207\u5f00\u86cb\u7cd5\uff0c\u5f00\u9500\u4e3a\u00a0verticalCut[j]\u00a0\u3002\n\n\u6bcf\u6b21\u64cd\u4f5c\u540e\uff0c\u8fd9\u5757\u86cb\u7cd5\u90fd\u88ab\u5207\u6210\u4e24\u4e2a\u72ec\u7acb\u7684\u5c0f\u86cb\u7cd5\u3002\n\n\u6bcf\u6b21\u64cd\u4f5c\u7684\u5f00\u9500\u90fd\u4e3a\u6700\u5f00\u59cb\u5bf9\u5e94\u5207\u5272\u7ebf\u7684\u5f00\u9500\uff0c\u5e76\u4e14\u4e0d\u4f1a\u6539\u53d8\u3002\n\n\u8bf7\u4f60\u8fd4\u56de\u5c06\u86cb\u7cd5\u5168\u90e8\u5207\u6210\u00a01 x 1\u00a0\u7684\u86cb\u7cd5\u5757\u7684\u00a0\u6700\u5c0f\u00a0\u603b\u5f00\u9500\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n\u8f93\u5165\uff1am = 3, n = 2, horizontalCut = [1,3], verticalCut = [5]\n\n\u8f93\u51fa\uff1a13\n\n\u89e3\u91ca\uff1a\n\n\t\u6cbf\u7740\u5782\u76f4\u7ebf 0 \u5207\u5f00\u86cb\u7cd5\uff0c\u5f00\u9500\u4e3a 5 \u3002\n\n\t\u6cbf\u7740\u6c34\u5e73\u7ebf 0 \u5207\u5f00\u00a03 x 1\u00a0\u7684\u86cb\u7cd5\u5757\uff0c\u5f00\u9500\u4e3a 1 \u3002\n\n\t\u6cbf\u7740\u6c34\u5e73\u7ebf 0 \u5207\u5f00 3 x 1\u00a0\u7684\u86cb\u7cd5\u5757\uff0c\u5f00\u9500\u4e3a 1 \u3002\n\n\t\u6cbf\u7740\u6c34\u5e73\u7ebf 1 \u5207\u5f00 2 x 1\u00a0\u7684\u86cb\u7cd5\u5757\uff0c\u5f00\u9500\u4e3a 3 \u3002\n\n\t\u6cbf\u7740\u6c34\u5e73\u7ebf 1 \u5207\u5f00 2 x 1\u00a0\u7684\u86cb\u7cd5\u5757\uff0c\u5f00\u9500\u4e3a 3 \u3002\n\n\u603b\u5f00\u9500\u4e3a\u00a05 + 1 + 1 + 3 + 3 = 13\u00a0\u3002\n\n\u793a\u4f8b 2\uff1a\n\n\u8f93\u5165\uff1am = 2, n = 2, horizontalCut = [7], verticalCut = [4]\n\n\u8f93\u51fa\uff1a15\n\n\u89e3\u91ca\uff1a\n\n\t\u6cbf\u7740\u6c34\u5e73\u7ebf 0 \u5207\u5f00\u86cb\u7cd5\uff0c\u5f00\u9500\u4e3a 7 \u3002\n\n\t\u6cbf\u7740\u5782\u76f4\u7ebf 0 \u5207\u5f00\u00a01 x 2\u00a0\u7684\u86cb\u7cd5\u5757\uff0c\u5f00\u9500\u4e3a 4 \u3002\n\n\t\u6cbf\u7740\u5782\u76f4\u7ebf 0 \u5207\u5f00\u00a01 x 2\u00a0\u7684\u86cb\u7cd5\u5757\uff0c\u5f00\u9500\u4e3a 4 \u3002\n\n\u603b\u5f00\u9500\u4e3a\u00a07 + 4 + 4 = 15\u00a0\u3002\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= m, n <= 105\n\n\thorizontalCut.length == m - 1\n\n\tverticalCut.length == n - 1\n\n\t1 <= horizontalCut[i], verticalCut[i] <= 103",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1am\u3001n\u3001horizontalCut\u3001verticalCut\u3002",
    "\u8f93\u51fa long \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def minimumCost(self, m: int, n: int, H: List[int], V: List[int]) -> int:  \n        H.sort(), V.sort()\n        h, v = 1, 1\n        res = 0\n        while H or V:\n            if not V or (H and H[-1] > V[-1]):\n                res += H.pop() * h\n                v += 1\n            else:\n                res += V.pop() * v\n                h += 1\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.minimumCost(_args[0], _args[1], _args[2], _args[3])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
