    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def maxXorSubsequences(self, nums: List[int]) -> int:\n        '''\n        \u7ebf\u6027\u57fa \u6a21\u677f\u9898\n        '''\n        level = 31\n        dt = {}\n        for num in nums:\n            for i in range(level,-1,-1):\n                s = 1 << i\n                if s&num:\n                    if s not in dt:\n                        dt[s] = num\n                        break\n                    else:\n                        num ^= dt[s]\n\n        # \u8bd5\u586b\u6cd5\u627e\u6700\u5927xor\n        res = 0\n        for i in range(level,-1,-1):\n            s = 1 << i\n            if s&res or s not in dt:\n                continue\n\n            res ^= dt[s]\n\n        return res\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxXorSubsequences(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
