    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1apoints\u3001direction\u3002",
    "\u8f93\u51fa integer[] \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def sub(self, a, b): # \u6c42\u70b9 a \u5230\u70b9 b \u7684\u5411\u91cf\n        return [a[0]-b[0], a[1]-b[1]]\n    \n    def cross(self, a, b):  # \u6c42\u5411\u91cf a \u5230\u5411\u91cf b \u7684\u5411\u91cf\u53c9\u79ef\n        return a[0] * b[1] - a[1] * b[0]\n    \n    def visitOrder(self, points: List[List[int]], direction: str) -> List[int]:\n        n = len(points)\n        used = [False] * n  # \u8bb0\u5f55\u70b9\u7684\u904d\u5386\u60c5\u51b5\uff0c False\u672a\u904d\u5386 / True\u5df2\u904d\u5386\n        order = [] # \u8bb0\u5f55\u8fd4\u56de\u7ed3\u679c\n        \n        # \u67e5\u627e\u6700\u5de6\u7684\u70b9\u4f5c\u4e3a \u8d77\u59cb\u70b9\n        start = 0\n        for i in range(0,n):\n            if points[i][0] < points[start][0]:\n                start = i\n        used[start] =True\n        order.append(start)\n        \n        for i in direction:\n            nxt = -1\n            if i=='L':\n                # \u8f6c\u5411\u65b9\u5411\u4e3a L\uff0c\u9009\u62e9\u76f8\u5bf9\u65b9\u5411\u6700\u53f3\u7684\u70b9\n                for j in range(0,n):\n                    if not used[j]:\n                        if nxt==-1 or self.cross(self.sub(points[nxt],points[start]), self.sub(points[j],points[start])) <0 :\n                            nxt = j\n            else:\n                # \u8f6c\u5411\u65b9\u5411\u4e3a R\uff0c\u9009\u62e9\u76f8\u5bf9\u65b9\u5411\u6700\u5de6\u7684\u70b9\n                for j in range(0,n):\n                    if not used[j]:\n                        if nxt==-1 or self.cross(self.sub(points[nxt],points[start]), self.sub(points[j],points[start])) >0 :\n                            nxt = j\n            # \u8fd4\u56de\u7ed3\u679c\u52a0\u5165\u9009\u62e9\u7684\u70b9\uff0c\u66f4\u65b0\u4e0b\u4e00\u6b21\u8f6c\u5411\u7684\u8d77\u70b9\n            used[nxt] = True\n            order.append(nxt)\n            start = nxt\n        \n        # \u6dfb\u52a0\u6700\u540e\u4e00\u4e2a\u5269\u4f59\u70b9\n        for i in range(0,n):\n            if not used[i]:\n                order.append(i)\n        return order\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.visitOrder(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
