    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3001k\u3002",
    "\u8f93\u51fa string \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def smallestBeautifulString(self, s: str, k: int) -> str:\n        for i in range(len(s) - 1, -1, -1):\n            blockedCharacters = set()\n            for j in range(1, 3):\n                if i - j >= 0:\n                    blockedCharacters.add(s[i - j])\n            for j in range(1, 4):\n                if ord(s[i]) - ord('a') + j + 1 <= k and chr(ord(s[i]) + j) not in blockedCharacters:\n                    return self.generate(s, i, j)\n        return \"\"\n\n    def generate(self, s: str, idx: str, offset: str) -> str:\n        res = list(s)\n        res[idx] = chr(ord(res[idx]) + offset)\n        for i in range(idx + 1, len(s)):\n            blockedCharacters = set()\n            for j in range(1, 3):\n                if i - j >= 0:\n                    blockedCharacters.add(res[i - j])\n            for j in range(3):\n                if chr(ord('a') + j) not in blockedCharacters:\n                    res[i] = chr(ord('a') + j)\n                    break\n        return ''.join(res)\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.smallestBeautifulString(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
