    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nfrom typing import List\r\n\r\n\r\nclass Solution:\r\n    def maxSum(self, nums: List[int], k: int) -> int:\r\n        mod: int = int(1e9 + 7)\r\n\r\n        bit: int = 32\r\n        # \u7edf\u8ba1\u4e8c\u8fdb\u5236\u6570\u4f4d\u4e2d\u6bcf\u5217\u76841\u4e2a\u7684\u4e2a\u6570\r\n        row = [0 for _ in range(bit)]\r\n        for num in nums:\r\n            for i in range(bit - 1, -1, -1):\r\n                row[i] += num >> i & 1\r\n\r\n        ans = 0\r\n        for _ in range(k):\r\n            temp = 0\r\n            # \u6784\u9020\u6700\u5927\u7684\u6570\r\n            for i in range(bit - 1, -1, -1):\r\n                if row[i] != 0:\r\n                    row[i] -= 1\r\n                    temp |= 1 << i\r\n            ans += (temp * temp) % mod\r\n            ans %= mod\r\n        return ans\r\n\r\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.maxSum(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
