    "hard",
    "\u5806/\u8d2a\u5fc3",
    "\u7ed9\u4f60\u4e00\u4e2a\u4e8c\u7ef4\u6574\u6570\u6570\u7ec4 intervals \uff0c\u5176\u4e2d intervals[i] = [starti, endi] \u8868\u793a\u4ece starti \u5230 endi \u7684\u6240\u6709\u6574\u6570\uff0c\u5305\u62ec starti \u548c endi \u3002\n\n\u5305\u542b\u96c6\u5408 \u662f\u4e00\u4e2a\u540d\u4e3a nums \u7684\u6570\u7ec4\uff0c\u5e76\u6ee1\u8db3 intervals \u4e2d\u7684\u6bcf\u4e2a\u533a\u95f4\u90fd \u81f3\u5c11 \u6709 \u4e24\u4e2a \u6574\u6570\u5728 nums \u4e2d\u3002\n\n\t\u4f8b\u5982\uff0c\u5982\u679c intervals = [[1,3], [3,7], [8,9]] \uff0c\u90a3\u4e48 [1,2,4,7,8,9] \u548c [2,3,4,8,9] \u90fd\u7b26\u5408 \u5305\u542b\u96c6\u5408 \u7684\u5b9a\u4e49\u3002\n\n\u8fd4\u56de\u5305\u542b\u96c6\u5408\u53ef\u80fd\u7684\u6700\u5c0f\u5927\u5c0f\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1aintervals = [[1,3],[3,7],[8,9]]\n\u8f93\u51fa\uff1a5\n\u89e3\u91ca\uff1anums = [2, 3, 4, 8, 9].\n\u53ef\u4ee5\u8bc1\u660e\u4e0d\u5b58\u5728\u5143\u7d20\u6570\u91cf\u4e3a 4 \u7684\u5305\u542b\u96c6\u5408\u3002\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1aintervals = [[1,3],[1,4],[2,5],[3,5]]\n\u8f93\u51fa\uff1a3\n\u89e3\u91ca\uff1anums = [2, 3, 4].\n\u53ef\u4ee5\u8bc1\u660e\u4e0d\u5b58\u5728\u5143\u7d20\u6570\u91cf\u4e3a 2 \u7684\u5305\u542b\u96c6\u5408\u3002\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1aintervals = [[1,2],[2,3],[2,4],[4,5]]\n\u8f93\u51fa\uff1a5\n\u89e3\u91ca\uff1anums = [1, 2, 3, 4, 5].\n\u53ef\u4ee5\u8bc1\u660e\u4e0d\u5b58\u5728\u5143\u7d20\u6570\u91cf\u4e3a 4 \u7684\u5305\u542b\u96c6\u5408\u3002\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\t1 <= intervals.length <= 3000\n\n\tintervals[i].length == 2\n\n\t0 <= starti < endi <= 108",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1aintervals\u3002",
    "\u8f93\u51fa integer \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def intersectionSizeTwo(self, intervals: List[List[int]]) -> int:\n        intervals.sort(key=lambda x: (x[0], -x[1]))\n        ans, n, m = 0, len(intervals), 2\n        vals = [[] for _ in range(n)]\n        for i in range(n - 1, -1, -1):\n            j = intervals[i][0]\n            for k in range(len(vals[i]), m):\n                ans += 1\n                for p in range(i - 1, -1, -1):\n                    if intervals[p][1] < j:\n                        break\n                    vals[p].append(j)\n                j += 1\n        return ans\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.intersectionSizeTwo(_args[0])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "int",
    [["[[1,3],[3,7],[8,9]]", "5"], ["[[1,3],[1,4],[2,5],[3,5]]", "3"], ["[[1,2],[2,3],[2,4],[4,5]]", "5"]],
