PHH14 = mk(
    "HH14",
    "\u68c0\u67e5\u5b57\u7b26\u4e32\u662f\u5426\u53ef\u4ee5\u901a\u8fc7\u6392\u5e8f\u5b50\u5b57\u7b26\u4e32\u5f97\u5230\u53e6\u4e00\u4e2a\u5b57\u7b26\u4e32",
    "LeetCode 1585",
    "hard",
    "\u5806/\u8d2a\u5fc3",
    "\u7ed9\u4f60\u4e24\u4e2a\u5b57\u7b26\u4e32\u00a0s \u548c\u00a0t\u00a0\uff0c\u8bf7\u4f60\u901a\u8fc7\u82e5\u5e72\u6b21\u4ee5\u4e0b\u64cd\u4f5c\u5c06\u5b57\u7b26\u4e32\u00a0s\u00a0\u8f6c\u5316\u6210\u5b57\u7b26\u4e32\u00a0t\u00a0\uff1a\n\n\t\u9009\u62e9 s\u00a0\u4e2d\u4e00\u4e2a \u975e\u7a7a\u00a0\u5b50\u5b57\u7b26\u4e32\u5e76\u5c06\u5b83\u5305\u542b\u7684\u5b57\u7b26\u5c31\u5730 \u5347\u5e8f\u00a0\u6392\u5e8f\u3002\n\n\u6bd4\u65b9\u8bf4\uff0c\u5bf9\u4e0b\u5212\u7ebf\u6240\u793a\u7684\u5b50\u5b57\u7b26\u4e32\u8fdb\u884c\u64cd\u4f5c\u53ef\u4ee5\u7531\u00a0\"14234\"\u00a0\u5f97\u5230\u00a0\"12344\"\u00a0\u3002\n\n\u5982\u679c\u53ef\u4ee5\u5c06\u5b57\u7b26\u4e32 s\u00a0\u53d8\u6210 t\u00a0\uff0c\u8fd4\u56de true\u00a0\u3002\u5426\u5219\uff0c\u8fd4\u56de false\u00a0\u3002\n\n\u4e00\u4e2a \u5b50\u5b57\u7b26\u4e32\u00a0\u5b9a\u4e49\u4e3a\u4e00\u4e2a\u5b57\u7b26\u4e32\u4e2d\u8fde\u7eed\u7684\u82e5\u5e72\u5b57\u7b26\u3002\n\n\u00a0\n\n\u793a\u4f8b 1\uff1a\n\n```\n\u8f93\u5165\uff1as = \"84532\", t = \"34852\"\n\u8f93\u51fa\uff1atrue\n\u89e3\u91ca\uff1a\u4f60\u53ef\u4ee5\u6309\u4ee5\u4e0b\u64cd\u4f5c\u5c06 s \u8f6c\u53d8\u4e3a t \uff1a\n\"84532\" \uff08\u4ece\u4e0b\u6807 2 \u5230\u4e0b\u6807 3\uff09-> \"84352\"\n\"84352\" \uff08\u4ece\u4e0b\u6807 0 \u5230\u4e0b\u6807 2\uff09 -> \"34852\"\n```\n\n\u793a\u4f8b 2\uff1a\n\n```\n\u8f93\u5165\uff1as = \"34521\", t = \"23415\"\n\u8f93\u51fa\uff1atrue\n\u89e3\u91ca\uff1a\u4f60\u53ef\u4ee5\u6309\u4ee5\u4e0b\u64cd\u4f5c\u5c06 s \u8f6c\u53d8\u4e3a t \uff1a\n\"34521\" -> \"23451\"\n\"23451\" -> \"23415\"\n```\n\n\u793a\u4f8b 3\uff1a\n\n```\n\u8f93\u5165\uff1as = \"12345\", t = \"12435\"\n\u8f93\u51fa\uff1afalse\n```\n\n\u793a\u4f8b 4\uff1a\n\n```\n\u8f93\u5165\uff1as = \"1\", t = \"2\"\n\u8f93\u51fa\uff1afalse\n```\n\n\u00a0\n\n\u63d0\u793a\uff1a\n\n\ts.length == t.length\n\n\t1 <= s.length <= 105\n\n\ts \u548c\u00a0t\u00a0\u90fd\u53ea\u5305\u542b\u6570\u5b57\u5b57\u7b26\uff0c\u5373\u00a0'0'\u00a0\u5230\u00a0'9' \u3002",
    "\u6bcf\u884c\u4e00\u4e2a\u53c2\u6570\uff08JSON \u683c\u5f0f\uff09\uff0c\u4f9d\u6b21\u4e3a\uff1as\u3001t\u3002",
    "\u8f93\u51fa boolean \u7c7b\u578b\u7ed3\u679c\uff08JSON \u5e8f\u5217\u5316\uff09\u3002",
    "",
    "import sys, json\nimport itertools, functools, collections, math, bisect, string, heapq, random, operator\nfrom typing import *\nfrom collections import *\nfrom itertools import *\nfrom bisect import *\nfrom functools import *\nfrom math import *\nfrom string import *\nfrom operator import *\n\nclass Solution:\n    def isTransformable(self, s: str, t: str) -> bool:\n        n = len(s)\n        pos = {i: collections.deque() for i in range(10)}\n        for i, digit in enumerate(s):\n            pos[int(digit)].append(i)\n        \n        for i, digit in enumerate(t):\n            d = int(digit)\n            if not pos[d]:\n                return False\n            if any(pos[j] and pos[j][0] < pos[d][0] for j in range(d)):\n                return False\n            pos[d].popleft()\n        \n        return True\n\ndef main():\n    _dec = json.JSONDecoder()\n    _text = sys.stdin.read()\n    _idx = 0\n    _args = []\n    while _idx < len(_text):\n        while _idx < len(_text) and _text[_idx] in ' \\t\\r\\n':\n            _idx += 1\n        if _idx >= len(_text):\n            break\n        try:\n            _obj, _end = _dec.raw_decode(_text, _idx)\n            _args.append(_obj)\n            _idx = _end\n        except Exception:\n            _nl = _text.find('\\n', _idx)\n            if _nl == -1:\n                _idx = len(_text)\n            else:\n                _idx = _nl + 1\n    _sol = Solution()\n\n    _ret = _sol.isTransformable(_args[0], _args[1])\n    if _ret is None:\n        _out = ''\n    elif isinstance(_ret, (list, dict)):\n        _out = json.dumps(_ret, separators=(',', ':'))\n    elif isinstance(_ret, bool):\n        _out = 'true' if _ret else 'false'\n    elif isinstance(_ret, float):\n        _out = repr(_ret)\n    else:\n        _out = str(_ret)\n    sys.stdout.write(_out)\n\nmain()\n",
    "bool",
    [["\"84532\"\n\"34852\"", "true"], ["\"34521\"\n\"23415\"", "true"], ["\"12345\"\n\"12435\"", "false"]],
    ["greedy", "string", "sorting", "\u5806/\u8d2a\u5fc3"],
    )
